-- Phase 1: auth, account and business (docs/api/phase1-auth-account-business.md).
-- IDs are UUIDs (generated by the application). Times are TIMESTAMPTZ (UTC).
-- Emails are stored lower-cased; phones are stored normalised as 0XXXXXXXX.

-- ── Account: users ───────────────────────────────────────────────────────────────────
-- "user" is reserved in PostgreSQL, hence "users".
CREATE TABLE users (
    id                  UUID          PRIMARY KEY,
    name                VARCHAR(80)   NOT NULL,
    email               VARCHAR(254),
    phone               VARCHAR(10),
    password_hash       VARCHAR(100),
    avatar_url          VARCHAR(500),
    pref_deals          BOOLEAN       NOT NULL DEFAULT TRUE,
    pref_promos         BOOLEAN       NOT NULL DEFAULT FALSE,
    failed_login_count  INTEGER       NOT NULL DEFAULT 0,
    locked_until        TIMESTAMPTZ,
    created_at          TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ   NOT NULL DEFAULT now(),
    CONSTRAINT ck_users_email_lower CHECK (email IS NULL OR email = lower(email)),
    CONSTRAINT ck_users_phone_format CHECK (phone IS NULL OR phone ~ '^0[1-9][0-9]{7,8}$'),
    CONSTRAINT ck_users_has_contact CHECK (email IS NOT NULL OR phone IS NOT NULL)
);

CREATE UNIQUE INDEX uq_users_email ON users (email) WHERE email IS NOT NULL;
CREATE UNIQUE INDEX uq_users_phone ON users (phone) WHERE phone IS NOT NULL;

-- Ways the user has signed in (SignInMethod). Added as they are used; never removed.
CREATE TABLE user_sign_in_method (
    user_id     UUID         NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    method      VARCHAR(20)  NOT NULL CHECK (method IN ('PASSWORD', 'GOOGLE', 'EMAIL_CODE', 'PHONE_SMS')),
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, method)
);

-- ── Auth: refresh-token sessions ─────────────────────────────────────────────────────
-- One row per refresh token. Rotation inserts a new row in the same family and marks the old
-- one rotated; presenting a rotated token again revokes the whole family (reuse detection).
CREATE TABLE user_session (
    id            UUID          PRIMARY KEY,
    user_id       UUID          NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    family_id     UUID          NOT NULL,
    token_hash    CHAR(64)      NOT NULL UNIQUE,
    rotated_from  UUID          REFERENCES user_session (id) ON DELETE SET NULL,
    rotated_at    TIMESTAMPTZ,
    revoked_at    TIMESTAMPTZ,
    expires_at    TIMESTAMPTZ   NOT NULL,
    user_agent    VARCHAR(300),
    ip            VARCHAR(64),
    created_at    TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ   NOT NULL DEFAULT now()
);

CREATE INDEX ix_user_session_user ON user_session (user_id) WHERE revoked_at IS NULL;
CREATE INDEX ix_user_session_family ON user_session (family_id);

-- ── Auth: one-time codes ─────────────────────────────────────────────────────────────
-- 6 digits, 10 min, resend after 30 s, 5 attempts. Only the SHA-256 hash is stored.
-- payload carries the pending sign-up (name + password hash) for VERIFY codes.
CREATE TABLE otp_code (
    id           UUID          PRIMARY KEY,
    purpose      VARCHAR(10)   NOT NULL CHECK (purpose IN ('VERIFY', 'LOGIN', 'RESET', 'PHONE')),
    target       VARCHAR(254)  NOT NULL,
    code_hash    CHAR(64)      NOT NULL,
    expires_at   TIMESTAMPTZ   NOT NULL,
    resend_at    TIMESTAMPTZ   NOT NULL,
    attempts     INTEGER       NOT NULL DEFAULT 0,
    consumed_at  TIMESTAMPTZ,
    payload      JSONB,
    created_at   TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at   TIMESTAMPTZ   NOT NULL DEFAULT now()
);

CREATE INDEX ix_otp_code_lookup ON otp_code (purpose, target, created_at DESC);

-- ── Auth: single-use tickets ─────────────────────────────────────────────────────────
-- RESET: issued after a RESET code, lets the holder set a new password (user_id set).
-- PHONE: issued after a PHONE code for an unknown number, lets the holder register (target = phone).
CREATE TABLE auth_ticket (
    id           UUID          PRIMARY KEY,
    kind         VARCHAR(10)   NOT NULL CHECK (kind IN ('RESET', 'PHONE')),
    token_hash   CHAR(64)      NOT NULL UNIQUE,
    user_id      UUID          REFERENCES users (id) ON DELETE CASCADE,
    target       VARCHAR(254)  NOT NULL,
    expires_at   TIMESTAMPTZ   NOT NULL,
    consumed_at  TIMESTAMPTZ,
    created_at   TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at   TIMESTAMPTZ   NOT NULL DEFAULT now()
);

-- ── Account: addresses ───────────────────────────────────────────────────────────────
CREATE TABLE address (
    id          UUID           PRIMARY KEY,
    user_id     UUID           NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    label       VARCHAR(10)    NOT NULL CHECK (label IN ('HOME', 'WORK', 'OTHER')),
    name        VARCHAR(80)    NOT NULL,
    phone       VARCHAR(10)    NOT NULL,
    line        VARCHAR(200)   NOT NULL,
    district    VARCHAR(80)    NOT NULL,
    note        VARCHAR(300),
    lat         NUMERIC(9, 6)  CHECK (lat BETWEEN -90 AND 90),
    lng         NUMERIC(9, 6)  CHECK (lng BETWEEN -180 AND 180),
    is_default  BOOLEAN        NOT NULL DEFAULT FALSE,
    created_at  TIMESTAMPTZ    NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ    NOT NULL DEFAULT now()
);

CREATE INDEX ix_address_user ON address (user_id, created_at);
-- At most one default address per user.
CREATE UNIQUE INDEX uq_address_default ON address (user_id) WHERE is_default;

-- ── Business ─────────────────────────────────────────────────────────────────────────
-- hours: JSON array of 7 entries (Monday first), each [openMin, closeMin] or null (closed).
-- closures: JSON array of {date, reason}.
-- product_settings (PRODUCT) / booking_settings (SERVICE): JSON objects per the domain model;
-- delivery zones live inside product_settings.zones.
CREATE TABLE business (
    id                UUID           PRIMARY KEY,
    owner_id          UUID           NOT NULL REFERENCES users (id),
    type              VARCHAR(10)    NOT NULL CHECK (type IN ('PRODUCT', 'SERVICE')),
    name              VARCHAR(80)    NOT NULL,
    slug              VARCHAR(90)    NOT NULL UNIQUE,
    category_id       VARCHAR(40)    NOT NULL REFERENCES category (id),
    about             VARCHAR(1000),
    phone             VARCHAR(10)    NOT NULL,
    email             VARCHAR(254),
    district          VARCHAR(80)    NOT NULL,
    street            VARCHAR(200)   NOT NULL,
    lat               NUMERIC(9, 6)  CHECK (lat BETWEEN -90 AND 90),
    lng               NUMERIC(9, 6)  CHECK (lng BETWEEN -180 AND 180),
    hours             JSONB          NOT NULL,
    closures          JSONB          NOT NULL DEFAULT '[]'::jsonb,
    online            BOOLEAN        NOT NULL DEFAULT TRUE,
    logo_url          VARCHAR(500),
    cover_url         VARCHAR(500),
    bakong_id         VARCHAR(100)   NOT NULL,
    verification      VARCHAR(10)    NOT NULL DEFAULT 'PENDING'
                                     CHECK (verification IN ('PENDING', 'VERIFIED', 'REJECTED')),
    rating            NUMERIC(2, 1)  NOT NULL DEFAULT 0 CHECK (rating BETWEEN 0 AND 5),
    review_count      INTEGER        NOT NULL DEFAULT 0,
    since             TIMESTAMPTZ    NOT NULL DEFAULT now(),
    product_settings  JSONB,
    booking_settings  JSONB,
    created_at        TIMESTAMPTZ    NOT NULL DEFAULT now(),
    updated_at        TIMESTAMPTZ    NOT NULL DEFAULT now(),
    CONSTRAINT ck_business_slug CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
    CONSTRAINT ck_business_settings CHECK (
        (type = 'PRODUCT' AND product_settings IS NOT NULL AND booking_settings IS NULL)
        OR (type = 'SERVICE' AND booking_settings IS NOT NULL AND product_settings IS NULL))
);

CREATE INDEX ix_business_owner ON business (owner_id);
CREATE INDEX ix_business_type_category ON business (type, category_id);

-- Members: Owner / Manager / Staff. user_id is null for staff without an account.
-- shifts: JSON array of 7 entries (Monday first), each [startMin, endMin] or null (off).
CREATE TABLE business_member (
    id           UUID          PRIMARY KEY,
    business_id  UUID          NOT NULL REFERENCES business (id) ON DELETE CASCADE,
    user_id      UUID          REFERENCES users (id) ON DELETE SET NULL,
    name         VARCHAR(80)   NOT NULL,
    role         VARCHAR(10)   NOT NULL CHECK (role IN ('OWNER', 'MANAGER', 'STAFF')),
    title        VARCHAR(80),
    color        VARCHAR(9),
    shifts       JSONB,
    active       BOOLEAN       NOT NULL DEFAULT TRUE,
    created_at   TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at   TIMESTAMPTZ   NOT NULL DEFAULT now()
);

CREATE INDEX ix_business_member_business ON business_member (business_id);
CREATE UNIQUE INDEX uq_business_member_user ON business_member (business_id, user_id) WHERE user_id IS NOT NULL;
CREATE INDEX ix_business_member_user ON business_member (user_id) WHERE user_id IS NOT NULL;

-- KYC documents uploaded during Create Business (the ID photo). Kept in the DB until the
-- storage domain (MinIO) exists; only reviewers read them.
CREATE TABLE business_document (
    id            UUID          PRIMARY KEY,
    business_id   UUID          NOT NULL REFERENCES business (id) ON DELETE CASCADE,
    kind          VARCHAR(20)   NOT NULL CHECK (kind IN ('ID_PHOTO')),
    content_type  VARCHAR(50)   NOT NULL,
    size_bytes    INTEGER       NOT NULL,
    data          BYTEA         NOT NULL,
    created_at    TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ   NOT NULL DEFAULT now()
);

CREATE INDEX ix_business_document_business ON business_document (business_id);
